    function isLoopbackHostname(hostname) {
      const host = typeof hostname === 'string' ? hostname.trim().toLowerCase() : '';
      if (!host) return true;
      return host === 'localhost' || host === '127.0.0.1' || host === '::1' || host === '[::1]';
    }
