    const CLOUD_SYNC_TOAST_MAX_AGE_MS = 30_000;
    const CLOUD_SYNC_TOAST_DURATION_OK_MS = 4000;
    const CLOUD_SYNC_TOAST_DURATION_WARN_MS = 6000;

    // 全局云同步 Toast 判定：去重、30 秒新鲜度过滤与不同状态自动关闭时长计算
    function resolveCloudSyncToastDecision(toast, lastSeenId, nowMs = Date.now()) {
      if (!toast || typeof toast !== 'object') return { action: 'ignore', nextLastSeenId: lastSeenId };
      const id = typeof toast.id === 'string' ? toast.id : String(toast.id ?? '');
      if (!id || id === lastSeenId) return { action: 'ignore', nextLastSeenId: lastSeenId };
      const createdAtMs = toast.createdAt != null && toast.createdAt !== ''
        ? (typeof toast.createdAt === 'number' ? toast.createdAt : Date.parse(toast.createdAt))
        : NaN;
      if (Number.isFinite(createdAtMs) && (nowMs - createdAtMs) > CLOUD_SYNC_TOAST_MAX_AGE_MS) {
        return { action: 'skip_stale', nextLastSeenId: id };
      }
      const status = toast.status === 'warn' ? 'warn' : 'ok';
      const durationMs = status === 'warn'
        ? CLOUD_SYNC_TOAST_DURATION_WARN_MS
        : CLOUD_SYNC_TOAST_DURATION_OK_MS;
      return {
        action: 'show',
        nextLastSeenId: id,
        toast,
        status,
        durationMs,
      };
    }
    // END resolveCloudSyncToastDecision

    function planScreenLockRemoteFrames({
      enabled,
      wasEnabled,
      wasLocked,
      isLocked,
      openedIds,
      activeId,
      suspended,
      readyIds,
      liveIds,
    } = {}) {
      // 开关关闭时不记住、不恢复，页面保持调用方的原样。
      if (enabled !== true) return { mode: 'keep', suspended: null };

      const openIds = (Array.isArray(openedIds) ? openedIds : []).filter((id) => typeof id === 'string' && id);
      const saved = suspended?.pending === true ? suspended : null;
      const lockingNow = isLocked === true && wasLocked !== true;
      const enableWhileLocked = isLocked === true && wasEnabled !== true && saved === null;
      if ((lockingNow || enableWhileLocked) && saved === null) {
        return {
          mode: 'suspend',
          suspended: {
            ids: openIds,
            activeId: typeof activeId === 'string' && activeId ? activeId : null,
            pending: true,
          },
        };
      }
      if (isLocked === true || saved === null) return { mode: 'keep', suspended: saved };

      const ready = new Set(Array.isArray(readyIds) ? readyIds : []);
      const live = new Set(Array.isArray(liveIds) ? liveIds : []);
      const knowLive = live.size > 0;
      const restoreIds = [];
      const waitingIds = [];
      for (const id of saved.ids || []) {
        if (typeof id !== 'string' || !id) continue;
        // 设备已经从列表消失就不再等；还没重新连上的继续等。
        if (knowLive && !live.has(id)) continue;
        if (ready.has(id)) restoreIds.push(id);
        else waitingIds.push(id);
      }
      if (restoreIds.length === 0) {
        if (waitingIds.length === 0) return { mode: 'keep', suspended: null };
        return {
          mode: 'wait',
          suspended: { ids: waitingIds, activeId: saved.activeId || null, pending: true },
        };
      }
      return {
        mode: 'restore',
        ids: restoreIds,
        activeId: saved.activeId && restoreIds.includes(saved.activeId) ? saved.activeId : null,
        suspended: waitingIds.length
          ? { ids: waitingIds, activeId: saved.activeId || null, pending: true }
          : null,
      };
    }
